  const signature = sign(null, Buffer.from(signingInput, "ascii"), privateKey);
  const token = `${signingInput}.${signature.toString("base64url")}`;

  const claims = verifyAccountLease({
    token,
    signingPublicKey: rawPublicKey(publicKey),
