      device_id: "device-id",
      iat: issuedAt,
      exp: expiresAt,
      v: 1,
    }),
  ).toString("base64url");
  const signingInput = `${header}.${payload}`;
  const accountLease = `${signingInput}.${sign(null, Buffer.from(signingInput, "ascii"), privateKey).toString("base64url")}`;
