content.text:
import {
  assertSigningKeyContinuity,
  verifyAccountLease,
} from "./accountLease.js";
import type { DesktopCredentialProfile } from "./credentialStore.js";
import type { HostedAuthCredentialStore } from "./hostedAuth.js";

export interface ResumeDesktopAccountOptions {
  readonly apiBaseUrl: string;
  readonly fetch: (input: string | URL, init?: RequestInit) => Promise<Response>;
  readonly credentialStore: HostedAuthCredentialStore;
  readonly currentTimeSeconds?: number;
}

export type DesktopAccountSession =
  | { readonly mode: "signed-out" }
  | { readonly mode: "offline"; readonly profile: DesktopCredentialProfile }
  | {
      readonly mode: "online";
      readonly accessToken: string;
      readonly accessTokenExpiresAt: number;
      readonly profile: DesktopCredentialProfile;
    };

function validateApiBaseUrl(value: string): URL {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    throw new TypeError("apiBaseUrl must be a valid URL");
  }
  if (url.protocol !== "https:" || url.username !== "" || url.password !== "") {
    throw new TypeError("apiBaseUrl must be an HTTPS URL without credentials");
  }
  url.pathname = `${url.pathname.replace(/\/+$/, "")}/`;
  url.search = "";
  url.hash = "";
  return url;
}

function assertOfflineLease(
  profile: DesktopCredentialProfile,
  currentTimeSeconds: number,
): void {
  let claims;
  try {
    claims = verifyAccountLease({
      token: profile.accountLease,
      signingPublicKey: profile.signingPublicKey,
      currentTimeSeconds,
    });
  } catch {
    throw new Error("desktop sign-in is required");
  }
  if (
    claims.userId !== profile.user.id ||
    claims.deviceId !== profile.deviceId ||
    claims.expiresAt !== profile.accountLeaseExpiresAt
  ) {
    throw new Error("desktop sign-in is required");
  }
}

function invalidRefresh(): never {
  throw new Error("desktop sign-in is required");
}

function refreshString(value: unknown): string {
  if (typeof value !== "string" || value.length === 0) {
    return invalidRefresh();
  }
  return value;
}

function refreshInteger(value: unknown): number {
  if (typeof value !== "number" || !Number.isSafeInteger(value)) {
    return invalidRefresh();
  }
  return value;
}

async function readRefreshSession(
  response: Response,
  currentProfile: DesktopCredentialProfile,
  currentTimeSeconds: number,
): Promise<DesktopAccountSession> {
  if (response.status !== 200) {
    return invalidRefresh();
  }
  let value: unknown;
  try {
    value = await response.json();
  } catch {
    return invalidRefresh();
  }
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return invalidRefresh();
  }
  const body = value as Record<string, unknown>;
  if (body.token_type !== "Bearer") {
    return invalidRefresh();
  }
  const accessToken = refreshString(body.access_token);
  const accessTokenExpiresAt = refreshInteger(body.access_token_expires_at);
  const refreshToken = refreshString(body.refresh_token);
  const refreshTokenExpiresAt = refreshInteger(body.refresh_token_expires_at);
  const accountLease = refreshString(body.account_lease);
  const accountLeaseExpiresAt = refreshInteger(body.account_lease_expires_at);
  const deviceId = refreshString(body.device_id);
  const signingPublicKey = assertSigningKeyContinuity(
    currentProfile.signingPublicKey,
    refreshString(body.signing_public_key),
  );
  const userValue = body.user;
  if (typeof userValue !== "object" || userValue === null || Array.isArray(userValue)) {
    return invalidRefresh();
  }
  const user = userValue as Record<string, unknown>;
  const userId = refreshString(user.id);
  const userEmail = refreshString(user.email);
  if (userId !== currentProfile.user.id || deviceId !== currentProfile.deviceId) {
    return invalidRefresh();
  }
  if (
    accessTokenExpiresAt <= currentTimeSeconds ||
    accessTokenExpiresAt - currentTimeSeconds > 15 * 60
  ) {
    return invalidRefresh();
  }
  if (
    refreshTokenExpiresAt <= currentTimeSeconds ||
    refreshTokenExpiresAt - currentTimeSeconds > 90 * 24 * 60 * 60
  ) {
    return invalidRefresh();
  }
  const claims = verifyAccountLease({
    token: accountLease,
    signingPublicKey,
    currentTimeSeconds,
  });
  if (
    claims.userId !== userId ||
    claims.deviceId !== deviceId ||
    claims.expiresAt !== accountLeaseExpiresAt
  ) {
    return invalidRefresh();
  }
  return {
    mode: "online",
    accessToken,
    accessTokenExpiresAt,
    profile: {
      version: 1,
      refreshToken,
      refreshTokenExpiresAt,
      accountLease,
      accountLeaseExpiresAt,
      signingPublicKey,
      deviceId,
      user: { id: userId, email: userEmail },
    },
  };
}


export async function resumeDesktopAccount(
  options: ResumeDesktopAccountOptions,
): Promise<DesktopAccountSession> {
  const apiBaseUrl = validateApiBaseUrl(options.apiBaseUrl);
  const currentTimeSeconds = options.currentTimeSeconds ?? Math.floor(Date.now() / 1_000);
  if (!Number.isSafeInteger(currentTimeSeconds) || currentTimeSeconds < 1) {
    throw new TypeError("currentTimeSeconds must be a positive integer");
  }
  const profile = await options.credentialStore.load();
  if (profile === null) {
    return { mode: "signed-out" };
  }

  let refreshResponse: Response;
  try {
    refreshResponse = await options.fetch(new URL("auth/desktop/refresh", apiBaseUrl), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ refresh_token: profile.refreshToken }),
      redirect: "error",
      signal: AbortSignal.timeout(15_000),
    });
  } catch {
    assertOfflineLease(profile, currentTimeSeconds);
    return { mode: "offline", profile };

[13 more lines in file. Use offset=191 to continue.]

    return { mode: "offline", profile };
  }
  if (refreshResponse.status >= 500 && refreshResponse.status <= 599) {
    assertOfflineLease(profile, currentTimeSeconds);
    return { mode: "offline", profile };
  }
  const session = await readRefreshSession(refreshResponse, profile, currentTimeSeconds);
  if (session.mode !== "online") {
    throw new Error("desktop refresh did not create an online session");
  }
  await options.credentialStore.save(session.profile);
  return session;
}

