import { writeFile } from 'node:fs/promises';
const [page] = await (await fetch('http://127.0.0.1:9333/json/list')).json();
const socket = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  socket.addEventListener('open', resolve, { once: true });
  socket.addEventListener('error', reject, { once: true });
});
let nextId = 1;
const command = (method, params = {}) => new Promise((resolve, reject) => {
  const id = nextId++;
  const listener = (event) => {
    const message = JSON.parse(event.data);
    if (message.id !== id) return;
    socket.removeEventListener('message', listener);
    if (message.error) reject(new Error(message.error.message));
    else resolve(message.result);
  };
  socket.addEventListener('message', listener);
  socket.send(JSON.stringify({ id, method, params }));
});
await command('Page.enable');
const result = await command('Page.captureScreenshot', { format: 'png', fromSurface: true });
await writeFile('/tmp/yinshi-signin.png', Buffer.from(result.data, 'base64'));
socket.close();
JS

