// Covers memory-only hosted access refresh, concurrency, and logout races.

import { describe, expect, it, vi } from "vitest";

import { HostedAccessSession } from "./hostedAccessSession.js";
import type { DesktopAccountSession } from "./accountSession.js";

const profile = {
  version: 1 as const,
  refreshToken: "refresh-token",
  refreshTokenExpiresAt: 2_000,
  accountLease: "lease-token",
  accountLeaseExpiresAt: 1_900,
  signingPublicKey: "signing-key",
  deviceId: "device-1",
  user: { id: "user-1", email: "owner@example.com" },
};

function online(accessToken: string): DesktopAccountSession {
  return {
    mode: "online",
    profile,
    accessToken,
    accessTokenExpiresAt: 1_500,
  };
}

describe("HostedAccessSession", () => {
  it("coalesces concurrent refreshes and keeps access tokens in memory", async () => {
    const resume = vi.fn(async () => online("a".repeat(40)));
    const session = new HostedAccessSession({ resume });

    const [first, second] = await Promise.all([
      session.getAccessToken(1_000),
      session.getAccessToken(1_000),
    ]);

    expect(first).toBe("a".repeat(40));
    expect(second).toBe(first);
    expect(resume).toHaveBeenCalledOnce();
    expect(session.profile).toEqual(profile);
  });

  it("cannot restore credentials when logout wins an in-flight refresh", async () => {
    let resolveResume: ((account: DesktopAccountSession) => void) | undefined;
    const resume = vi.fn(
      () =>
        new Promise<DesktopAccountSession>((resolve) => {
          resolveResume = resolve;
        }),
    );
    const session = new HostedAccessSession({ resume });
    const refresh = session.getAccessToken(1_000);

    session.clear();
    resolveResume?.(online("b".repeat(40)));

    await expect(refresh).rejects.toThrow("account changed");
    expect(session.profile).toBeUndefined();
    await expect(session.getCachedAccessToken(1_000)).resolves.toBeUndefined();
  });
});

import type { DesktopAccountSession } from "./accountSession.js";
import type { DesktopCredentialProfile } from "./credentialStore.js";

export interface HostedAccessSessionOptions {
  readonly resume: (currentTimeSeconds: number) => Promise<DesktopAccountSession>;
}

export class HostedAccessSession {
  readonly #resume: HostedAccessSessionOptions["resume"];
  #profile: DesktopCredentialProfile | undefined;
  #accessToken: string | undefined;
  #accessTokenExpiresAt: number | undefined;
  #refresh: Promise<string> | undefined;
  #epoch = 0;

  constructor(options: HostedAccessSessionOptions) {
    if (typeof options.resume !== "function") {
      throw new TypeError("HostedAccessSession requires a resume function");
    }
    this.#resume = options.resume;
  }

  get profile(): DesktopCredentialProfile | undefined {
    return this.#profile;
  }

  setAccount(account: DesktopAccountSession): void {
    if (account === null || typeof account !== "object") {
      throw new TypeError("Hosted account session must be an object");
    }
    this.#epoch += 1;
    this.#applyAccount(account);
  }

  clear(): void {
    this.#epoch += 1;
    this.#profile = undefined;
    this.#accessToken = undefined;
    this.#accessTokenExpiresAt = undefined;
    this.#refresh = undefined;
  }

  async getCachedAccessToken(currentTimeSeconds: number): Promise<string | undefined> {
    this.#requireCurrentTime(currentTimeSeconds);
    if (
      this.#accessToken === undefined ||
      this.#accessTokenExpiresAt === undefined ||
      this.#accessTokenExpiresAt <= currentTimeSeconds + 30
    ) {
      return undefined;
    }
    return this.#accessToken;
  }

  async getAccessToken(currentTimeSeconds: number): Promise<string> {
    const cachedToken = await this.getCachedAccessToken(currentTimeSeconds);
    if (cachedToken !== undefined) {
      return cachedToken;
    }
    if (this.#refresh !== undefined) {
      return this.#refresh;
    }

    const refreshEpoch = this.#epoch;
    const refreshPromise = (async () => {
      const account = await this.#resume(currentTimeSeconds);
      if (this.#epoch !== refreshEpoch) {
        throw new Error("Hosted account changed while access was refreshing");
      }
      this.#applyAccount(account);
      if (account.mode !== "online") {
        throw new Error("Hosted account is offline");
      }
      return account.accessToken;
    })();
    this.#refresh = refreshPromise;
    try {
      return await refreshPromise;
    } finally {
      if (this.#refresh === refreshPromise) {
        this.#refresh = undefined;
      }
    }
  }

  #applyAccount(account: DesktopAccountSession): void {
    this.#profile = account.mode === "signed-out" ? undefined : account.profile;
    this.#accessToken = account.mode === "online" ? account.accessToken : undefined;
    this.#accessTokenExpiresAt =
      account.mode === "online" ? account.accessTokenExpiresAt : undefined;
  }

  #requireCurrentTime(currentTimeSeconds: number): void {
    if (!Number.isSafeInteger(currentTimeSeconds) || currentTimeSeconds < 0) {
      throw new RangeError("currentTimeSeconds must be a non-negative integer");
    }
  }
}

